def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper 3-colorings of the grid consistent with its fixed cells."""
    MOD = 998244353

    # Keep the frontier narrow. Transposition preserves edge adjacency.
    if W > H:
        grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    powers = [3 ** i for i in range(W)]
    row_options = []
    for row in grid:
        options = []
        digits = [0] * W

        def build(col, code):
            if col == W:
                options.append((code, tuple(digits)))
                return
            ch = row[col]
            choices = range(3) if ch == '?' else (int(ch) - 1,)
            for d in choices:
                if col and digits[col - 1] == d:
                    continue
                digits[col] = d
                build(col + 1, code + d * powers[col])

        build(0, 0)
        row_options.append(options)

    allowed = []
    for options in row_options:
        table = bytearray(3 ** W)
        for code, _ in options:
            table[code] = 1
        allowed.append(table)

    dp = {code: 1 for code, _ in row_options[0]}
    for r in range(1, H):
        next_dp = {}
        table = allowed[r]
        for old_code, count in dp.items():
            x = old_code
            prev = [0] * W
            for c in range(W):
                prev[c] = x % 3
                x //= 3

            def extend(col, last, code):
                if col == W:
                    if table[code]:
                        next_dp[code] = (next_dp.get(code, 0) + count) % MOD
                    return
                forbidden = prev[col]
                for d in range(3):
                    if d != forbidden and d != last:
                        extend(col + 1, d, code + d * powers[col])

            extend(0, -1, 0)
        dp = next_dp
    return sum(dp.values()) % MOD

