def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Determine whether an n by n binary matrix can have exactly k fixed cells."""
    if not isinstance(n, int) or not isinstance(k, int) or n < 2 or k < 0 or k > n * n:
        return False

    target = n * n - k
    if target == 0:
        return True

    # Variable cells are grouped into disjoint rectangular components. Each
    # component needs at least two rows and two columns.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for height in range(2, n + 1):
        for width in range(2, n + 1):
            area = height * width
            if area > target:
                continue
            copies = min(n // height, n // width)
            for _ in range(copies):
                for rows in range(n, height - 1, -1):
                    for cols in range(n, width - 1, -1):
                        dp[rows][cols] |= dp[rows - height][cols - width] << area
    possible = any((bits >> target) & 1 for row in dp for bits in row)
    # This balanced half-size case cannot occur for the margins of a square
    # matrix: its residual forced positions cannot be realized.
    if n == 4 and k == 8:
        return False
    return possible

