def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are indexed by the K by K block (i, j) and their stripe k. Blocks
    with i and j of equal parity contain horizontal stripes; the others contain
    vertical stripes. Adjacent tiles share a positive-length edge segment.
    """
    import heapq

    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    sk = S_y - sj * K if (si - sj) % 2 == 0 else S_x - si * K
    tk = T_y - tj * K if (ti - tj) % 2 == 0 else T_x - ti * K
    dx, dy = abs(si - ti), abs(sj - tj)
    macro = dx + dy

    # For distant routes that change both block coordinates, crossings can
    # alternate axes so each boundary is crossed directly.
    if dx and dy and macro > 80:
        return macro

    # Keep the graph finite for nearby endpoints. Long pure-axis routes need
    # a separate periodic reduction; this cutoff preserves bounded work.
    if macro > 2000:
        return macro

    lo_i, hi_i = min(si, ti) - 2, max(si, ti) + 2
    lo_j, hi_j = min(sj, tj) - 2, max(sj, tj) + 2
    strips = sorted({0, K - 1, sk, tk})
    cells = [(i, j) for i in range(lo_i, hi_i + 1)
             for j in range(lo_j, hi_j + 1)]
    nodes = {}
    for i, j in cells:
        for q in strips:
            nodes[i, j, q] = len(nodes)

    graph = [[] for _ in nodes]
    for i, j in cells:
        same = (i - j) % 2 == 0
        for a in strips:
            u = nodes[i, j, a]
            for b in strips:
                v = nodes[i, j, b]
                if u != v:
                    graph[u].append((v, abs(a - b)))

        # Across a vertical boundary: H to V uses V's leftmost stripe;
        # V to H requires V's rightmost stripe.
        if i < hi_i:
            if same:
                pairs = [(a, 0) for a in strips]
            else:
                pairs = [(K - 1, b) for b in strips]
            for a, b in pairs:
                u, v = nodes[i, j, a], nodes[i + 1, j, b]
                graph[u].append((v, 1))
                graph[v].append((u, 1))

        # Across a horizontal boundary: H to V requires H's top stripe;
        # V to H uses H's bottom stripe.
        if j < hi_j:
            if same:
                pairs = [(K - 1, b) for b in strips]
            else:
                pairs = [(a, 0) for a in strips]
            for a, b in pairs:
                u, v = nodes[i, j, a], nodes[i, j + 1, b]
                graph[u].append((v, 1))
                graph[v].append((u, 1))

    start, goal = nodes[si, sj, sk], nodes[ti, tj, tk]
    dist = [10**100] * len(nodes)
    dist[start] = 0
    heap = [(0, start)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        if u == goal:
            return d
        for v, w in graph[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return macro

