def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Determine whether an n by n binary matrix can have exactly k fixed cells.

    A cell is fixed when its value is the same in every binary matrix with
    the same ordered row sums and ordered column sums.
    """
    if not (0 <= k <= n * n):
        return False

    # A flexible block of a rows by b columns can be made so every cell can
    # change while preserving its margins. Separate such blocks by zero rows
    # and columns; all cells outside the blocks are then fixed. This computes
    # all fixed-cell counts obtained by this general block construction.
    target = n * n - k
    reachable = [[set() for _ in range(n + 1)] for _ in range(n + 1)]
    reachable[0][0].add(0)
    for used_rows in range(n + 1):
        for used_cols in range(n + 1):
            for area in tuple(reachable[used_rows][used_cols]):
                for rows in range(2, n - used_rows + 1):
                    for cols in range(2, n - used_cols + 1):
                        reachable[used_rows + rows][used_cols + cols].add(
                            area + rows * cols
                        )
    return any(target in reachable[r][c]
               for r in range(n + 1) for c in range(n + 1))

