from functools import lru_cache
from math import isqrt

MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M positive-integer sequences whose product is at most N
    and whose product has divisor sum divisible by 3.
    """
    if N < 1:
        return 0

    B = isqrt(N)
    L = N // B
    large = [N // i for i in range(1, B + 1)]
    small = list(range(L - 1, 0, -1))
    vals = large + small
    size = len(vals)

    def idx(x):
        if x >= L:
            return N // x - 1
        return B + (L - 1 - x)

    limit = B
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0:2] = b"\x00\x00"
    primes = []
    for p in range(2, limit + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= limit:
                sieve[p * p:limit + 1:p] = b"\x00" * ((limit - p * p) // p + 1)

    # Residue-class prime counts for every distinct floor(N/i), represented
    # in the standard high/low quotient layout.
    g = [[0] * size for _ in range(3)]
    for i, v in enumerate(vals):
        g[0][i] = v // 3
        g[1][i] = (v + 2) // 3 - 1
        g[2][i] = (v + 1) // 3

    prefix = [[0] * (B + 1) for _ in range(3)]
    for x in range(1, B + 1):
        for r in range(3):
            prefix[r][x] = prefix[r][x - 1]
        if sieve[x]:
            prefix[x % 3][x] += 1

    for p in primes:
        if p * p > N:
            break
        before = [prefix[r][p - 1] for r in range(3)]
        p2 = p * p
        for i, v in enumerate(vals):
            if v < p2:
                break
            qid = idx(v // p)
            for r in range(3):
                g[(r * p) % 3][i] -= g[r][qid] - before[r]

    def prime_counts(x):
        if x < 2:
            return (0, 0, 0)
        if x <= B:
            return tuple(prefix[r][x] for r in range(3))
        i = idx(x)
        return (g[0][i], g[1][i], g[2][i])

    def prime_sum(x, complement):
        c = prime_counts(x)
        return M * (c[0] + c[1] + (0 if complement else c[2])) % MOD

    choose = [1] * (N.bit_length() + 1)
    for e in range(1, len(choose)):
        choose[e] = choose[e - 1] * (M + e - 1) % MOD * pow(e, MOD - 2, MOD) % MOD

    def trigger(p, e):
        return (p % 3 == 2 and e % 2 == 1) or (p % 3 == 1 and e % 3 == 2)

    @lru_cache(None)
    def rough(x, start, complement):
        if x < 2:
            return 1
        root = isqrt(x)
        lower = primes[start - 1] if start else 1
        ans = (prime_sum(x, complement) -
               prime_sum(max(root, lower), complement)) % MOD
        for j in range(start, len(primes)):
            p = primes[j]
            if p > root:
                break
            power = p
            e = 1
            while power <= x:
                if not complement or not trigger(p, e):
                    ans = (ans + choose[e] * rough(x // power, j + 1, complement)) % MOD
                power *= p
                e += 1
        return (ans + 1) % MOD

    return (rough(N, 0, False) - rough(N, 0, True)) % MOD

