from typing import List

MOD = 998244353


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Given a lowercase English string s of length n, count length-m strings
    by the length of their LCS with s, modulo 998244353.
    """
    # A row of the usual LCS table summarizes all information needed to
    # process one more character. There are at most 2**n distinct rows.
    start = (0,) * (n + 1)
    states = {start: 1}
    for _ in range(m):
        nxt = {}
        for row, ways in states.items():
            for code in range(26):
                ch = chr(ord("a") + code)
                updated = [0] * (n + 1)
                for i in range(1, n + 1):
                    match = row[i - 1] + (s[i - 1] == ch)
                    updated[i] = max(row[i], updated[i - 1], match)
                key = tuple(updated)
                nxt[key] = (nxt.get(key, 0) + ways) % MOD
        states = nxt

    result = [0] * (n + 1)
    for row, ways in states.items():
        result[row[n]] = (result[row[n]] + ways) % MOD
    return result

