def _count_upto(bound: str, min_sum: int, max_sum: int) -> int:
    """Count nonnegative integers up to bound with an allowed digit sum."""
    max_sum = min(max_sum, 9 * len(bound))
    if min_sum > max_sum:
        return 0

    less = [0] * (max_sum + 1)
    equal_sum = 0
    for ch in bound:
        digit = ord(ch) - 48
        new_less = [0] * (max_sum + 1)
        for total, ways in enumerate(less):
            if ways:
                for d in range(10):
                    if total + d <= max_sum:
                        new_less[total + d] = (new_less[total + d] + ways) % MOD
        for d in range(digit):
            total = equal_sum + d
            if total <= max_sum:
                new_less[total] = (new_less[total] + 1) % MOD
        equal_sum += digit
        less = new_less
    answer = sum(less[min_sum:max_sum + 1])
    if min_sum <= equal_sum <= max_sum:
        answer += 1
    return answer % MOD


def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers x in [num1, num2] whose digit sum is in [min_sum, max_sum].

    Return the count modulo 10^9 + 7.
    """
    def decrement(value: str) -> str | None:
        digits = list(value)
        i = len(digits) - 1
        while i >= 0 and digits[i] == "0":
            digits[i] = "9"
            i -= 1
        if i < 0:
            return None
        digits[i] = str(int(digits[i]) - 1)
        return "".join(digits).lstrip("0") or "0"

    lower = decrement(num1)
    upper_count = _count_upto(num2, min_sum, max_sum)
    lower_count = _count_upto(lower, min_sum, max_sum) if lower is not None else 0
    return (upper_count - lower_count) % MOD

